                    self.id_maps[table][row["visit_id"]] = row["visit_id"]
                elif "diag_id" in row:
                    self.id_maps[table][row["diag_id"]] = row["diag_id"]
                elif "med_id" in row:
                    self.id_maps[table][row["med_id"]] = row["med_id"]
                elif "lab_id" in row:
                    self.id_maps[table][row["lab_id"]] = row["lab_id"]
                self.tables[table].append(row)

    def to_dataframe(self) -> Dict[str, pd.DataFrame]:
        return {t: pd.DataFrame(rows) for t, rows in self.tables.items()}

    def export_csv(self, out_dir: str):
        df_dict = self.to_dataframe()
        for table, df in df_dict.items():
            df.to_csv(f"{out_dir}/{table}.csv", index=False)
```

---

## 7. Usage Example

```python
# generate_synthetic_ehr.py
from src.generator import SyntheticEHRGenerator
import os

if __name__ == "__main__":
    # 1. Load generator
    gen = SyntheticEHRGenerator("data/config.yaml")

    # 2. Ask for 10 patients, each with 1–3 visits, etc.
    counts = {
        "patient": 10,
        "visit": 30,          # 3 visits per patient on average
        "diagnosis": 45,      # 1.5 diagnoses per visit
        "medication": 50,     # 1.7 meds per visit
        "lab": 60            # 2 labs per visit
    }

    gen.generate(counts)

    # 3. Export to CSV
    out_dir = "output"
    os.makedirs(out_dir, exist_ok=True)
    gen.export_csv(out_dir)

    print(f"Synthetic EHR data written to {out_dir}")
```

Run:

```bash
python generate_synthetic_ehr.py
```

You’ll find five CSV files: `patient.csv`, `visit.csv`, `diagnosis.csv`, `medication.csv`, `lab.csv`.

